// #487826 (38c0a78f545c8aeac8487826) — лист «צריכים עזרה?», открытый из сбоя тех. проверки (нет mediaDevices /
// NotAllowedError / NotReadableError / прочая ошибка), открывается с выбранным «תקלה טכנית» и описанием сбоя; из мест
// без сбоя — без выбора и с пустым описанием. Кейс CALL-021.
// Сбой подменяется до загрузки страницы (addInitScript): по отдельному окну на сбой, кандидат один на файл.
// НЕ prod-safe: создаётся кандидат «QA-AUTO-HELP-…» (business, link_only — без письма/SMS), не удаляется (правило
// проекта) → @data. Обращение НЕ отправляется («שליחה» не нажимается), звонок не начинается (blockCallStarts).
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { blockCallStarts } from './support';
import { A11Y, SCREENS, newCandidateLink, tapBtn, NO_MEDIA_DEVICES } from './a11y-support';

const HASH = '#487826 · #38c0a78f545c8aeac8487826';
test.describe.configure({ mode: 'serial' });

const TXT = {
  startCheck: 'להתחיל בדיקה',
  failLink: 'נתקלת בבעיה? פנייה לגורם אנושי',
  unsupportedCta: 'פנייה לגורם אנושי',
  technical: 'תקלה טכנית',
  description: 'תיאור הפנייה',
  prefix: 'הבדיקה הטכנית לא מצליחה: ',
};

type Mode = 'NotAllowedError' | 'NotReadableError' | 'QAUnknownError' | 'pending';

/** Подмена getUserMedia до загрузки страницы: отказ с нужным DOMException или «ждём разрешения» (не отвечает). */
const failGetUserMedia = (mode: Mode) => {
  const md = navigator.mediaDevices;
  if (!md) return;
  const fake = () => (mode === 'pending' ? new Promise<MediaStream>(() => {}) : Promise.reject(new DOMException('qa mock', mode)));
  try {
    Object.defineProperty(md, 'getUserMedia', { value: fake, configurable: true, writable: true });
  } catch {
    (md as unknown as { getUserMedia: unknown }).getUserMedia = fake;
  }
};

let link = '';

/** От ссылки до экрана тех. проверки: вступление → פרטי הלקוח → согласие (если сервер ещё не помнит согласие). */
async function toTechCheck(page: Page, stopAt: RegExp | string) {
  await page.goto(link);
  const welcome = page.getByRole('button', { name: A11Y.welcomeCta });
  const target = typeof stopAt === 'string' ? page.getByRole('button', { name: stopAt }) : page.getByText(stopAt);
  await expect(welcome.or(target).first()).toBeVisible({ timeout: 30_000 });
  if (await welcome.isVisible()) {
    for (const s of SCREENS) await tapBtn(page, s.ready);
    await page.getByRole('checkbox').first().check();
    await tapBtn(page, A11Y.consentCta);
  }
  await expect(target.first()).toBeVisible({ timeout: 30_000 });
}

/** Открыть лист помощи кнопкой, проверить выбранный тип и описание, закрыть (ничего не отправляя). */
async function expectHelp(page: Page, open: () => Promise<void>, expected: { technical: boolean; message: string }, where: string) {
  await open();
  await expect(page.getByText(A11Y.helpTitle, { exact: true }).filter({ visible: true }).first(), `лист помощи (${where})`).toBeVisible();
  const technical = page.getByRole('radio', { name: TXT.technical });
  if (expected.technical) {
    await expect(technical, `«${TXT.technical}» выбрано (${where})`).toBeChecked();
  } else {
    await expect(page.getByRole('radio', { checked: true }), `тип не выбран (${where})`).toHaveCount(0);
  }
  await expect(page.getByRole('textbox', { name: TXT.description }), `описание (${where})`).toHaveValue(expected.message);
  await tapBtn(page, A11Y.helpClose);
  await expect(page.getByText(A11Y.helpTitle, { exact: true }).filter({ visible: true })).toHaveCount(0);
}

const headerHelp = (page: Page) => () => page.getByTestId('help-entry').filter({ visible: true }).first().click();
const button = (page: Page, name: string) => () => page.getByRole('button', { name, exact: true }).first().click();

const FAILURES: { id: string; mode: Mode | 'no-media-devices'; screen: RegExp; link: string; message: string }[] = [
  { id: 'нет navigator.mediaDevices', mode: 'no-media-devices', screen: /הדפדפן הזה לא מאפשר שימוש במיקרופון/, link: TXT.unsupportedCta, message: `${TXT.prefix}הדפדפן לא מאפשר מיקרופון.` },
  { id: 'NotAllowedError', mode: 'NotAllowedError', screen: /המיקרופון חסום/, link: TXT.failLink, message: `${TXT.prefix}המיקרופון חסום בדפדפן.` },
  { id: 'NotReadableError', mode: 'NotReadableError', screen: /הבדיקה לא הצליחה/, link: TXT.failLink, message: `${TXT.prefix}המיקרופון תפוס על ידי תוכנה אחרת.` },
  { id: 'прочая ошибка', mode: 'QAUnknownError', screen: /הבדיקה לא הצליחה/, link: TXT.failLink, message: `${TXT.prefix}משהו השתבש בגישה למיקרופון.` },
];

test.describe(`Кандидат — помощь из сбоя тех. проверки (${HASH})`, () => {
  test.beforeAll(async ({ browser }, testInfo) => {
    const baseURL = testInfo.project.use.baseURL as string;
    const name = `QA-AUTO-HELP-${runStamp()}`;
    link = await newCandidateLink(browser, name, baseURL);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (согласие, тех. проверка не пройдена), не удаляется` });
  });

  test(`сбои тех. проверки (нет mediaDevices / NotAllowedError / NotReadableError / прочая) → ссылка помощи и «?»: «תקלה טכנית» выбрана, описание по сбою @iphone @data ${HASH}`, async ({ asUser }) => {
    test.setTimeout(4 * 60_000);
    for (const f of FAILURES) {
      const page = await asUser('guest');
      if (f.mode === 'no-media-devices') await page.addInitScript(NO_MEDIA_DEVICES);
      else await page.addInitScript(failGetUserMedia, f.mode);
      const blocked = await blockCallStarts(page);

      if (f.mode === 'no-media-devices') {
        await toTechCheck(page, f.screen);
      } else {
        await toTechCheck(page, TXT.startCheck);
        await tapBtn(page, TXT.startCheck);
        await expect(page.getByText(f.screen).first(), `экран сбоя (${f.id})`).toBeVisible({ timeout: 30_000 });
      }

      // Источник: AC1 — из сбоя тех. проверки «תקלה טכנית» выбрано и описание, как в кадре 827:2940.
      const expected = { technical: true, message: f.message };
      await expectHelp(page, button(page, f.link), expected, `${f.id}: ссылка «${f.link}»`);
      await expectHelp(page, headerHelp(page), expected, `${f.id}: «?» в шапке`);
      expect(blocked.start + blocked.voice, `старт попытки (${f.id})`).toBe(0);
      await page.close();
    }
  });

  test(`без сбоя (вступление тех. проверки, ожидание разрешения) → «?» и ссылка помощи: тип не выбран, описание пустое @iphone @data ${HASH}`, async ({ asUser }) => {
    test.setTimeout(3 * 60_000);
    const page = await asUser('guest');
    await page.addInitScript(failGetUserMedia, 'pending' as Mode);
    const blocked = await blockCallStarts(page);
    const empty = { technical: false, message: '' };

    // Источник: AC2 — «מכל מקום אחר הגיליון נפתח ריק».
    await toTechCheck(page, TXT.startCheck);
    await expectHelp(page, headerHelp(page), empty, 'вступление тех. проверки: «?»');

    await tapBtn(page, TXT.startCheck);
    await expect(page.getByText('אשרו גישה למיקרופון').first()).toBeVisible({ timeout: 30_000 });
    await expectHelp(page, button(page, TXT.failLink), empty, `ожидание разрешения: «${TXT.failLink}»`);
    await expectHelp(page, headerHelp(page), empty, 'ожидание разрешения: «?»');
    expect(blocked.start + blocked.voice, 'старт попытки').toBe(0);
  });
});
